#include "banker.h"
#include <limits.h>
#include <stdio.h>
#include <string.h>

static DlValidation bad(const char *message){DlValidation v={.ok=false};snprintf(v.message,sizeof v.message,"%s",message);return v;}
DlValidation dl_banker_validate(const DlBankerScenario*b){if(!b)return bad("Banker's scenario is required");if(!memchr(b->id,0,sizeof b->id))return bad("scenario identifier is not terminated");if(b->process_count>DL_MAX_PROCESSES||b->resource_count>DL_MAX_RESOURCES)return bad("scenario exceeds configured process/resource limits");DlScenario state;memset(&state,0,sizeof state);snprintf(state.id,sizeof state.id,"%s",b->id);state.process_count=b->process_count;state.resource_count=b->resource_count;memcpy(state.processes,b->processes,sizeof state.processes);memcpy(state.resources,b->resources,sizeof state.resources);memcpy(state.total,b->total,sizeof state.total);memcpy(state.available,b->available,sizeof state.available);memcpy(state.allocation,b->allocation,sizeof state.allocation);for(size_t i=0;i<b->process_count;i++)for(size_t j=0;j<b->resource_count;j++){if(b->maximum[i][j]<0)return bad("maximum claims must be non-negative");if(b->allocation[i][j]>b->maximum[i][j])return bad("allocation cannot exceed maximum claim");}return dl_validate(&state);}
DlValidation dl_banker_safety(const DlBankerScenario*b,DlBankerResult*out){DlValidation v=dl_banker_validate(b);if(!v.ok)return v;if(!out)return bad("Banker's result is required");memset(out,0,sizeof *out);int work[DL_MAX_RESOURCES]={0};bool finish[DL_MAX_PROCESSES]={false};for(size_t j=0;j<b->resource_count;j++)work[j]=b->available[j];for(size_t i=0;i<b->process_count;i++)finish[i]=false;bool progress;do{progress=false;for(size_t i=0;i<b->process_count;i++)if(!finish[i]){if(out->trace_count>=DL_MAX_PROCESSES*(DL_MAX_PROCESSES+1))return bad("Banker's trace capacity exceeded");DlBankerStep*t=&out->trace[out->trace_count++];t->process_index=i;t->eligible=true;for(size_t j=0;j<b->resource_count;j++){t->work_before[j]=work[j];t->need[j]=b->maximum[i][j]-b->allocation[i][j];if(t->need[j]>work[j])t->eligible=false;}if(t->eligible){for(size_t j=0;j<b->resource_count;j++){if(work[j]>INT_MAX-b->allocation[i][j])return bad("Banker's work arithmetic overflow");work[j]+=b->allocation[i][j];}finish[i]=true;out->sequence[out->sequence_count++]=i;progress=true;}for(size_t j=0;j<b->resource_count;j++)t->work_after[j]=work[j];}}while(progress);out->safe=out->sequence_count==b->process_count;for(size_t i=0;i<b->process_count;i++)if(!finish[i])out->unfinished[out->unfinished_count++]=i;return (DlValidation){.ok=true,.message=""};}
